$ENTRY Go { (e.A) (e.B) (e.C) = <Candidate (e.A) (e.B) (e.C)>; }
Reference { (e.A) (e.B) (e.C) = <Append <Append (e.A) (e.B)> (e.C)>; }
Candidate { (e.A) (e.B) (e.C) = <Append (e.A) <Append (e.B) (e.C)>>; }

Append {
  (e.A) (e.B) = (<Append-Contents (e.A) (e.B)>);
}
Append-Contents {
  () (e.B) = e.B;
  (t.H e.T) (e.B) = t.H <Append-Contents (e.T) (e.B)>;
}
